package ghjira

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"testing"
)

// golden.json was generated by the Python implementation this package replaced.
// Digests, tokens (which become Jira labels), and text conversion must stay
// byte-identical so existing state and Jira issues keep matching.
type golden struct {
	Config  Object `json:"config"`
	Binding string `json:"binding"`
	Tokens  []struct {
		Kind  string `json:"kind"`
		ID    any    `json:"id"`
		Token string `json:"token"`
	} `json:"tokens"`
	Digests []struct {
		Value  any    `json:"value"`
		Digest string `json:"digest"`
	} `json:"digests"`
	ToADF []struct {
		Text string `json:"text"`
		ADF  Object `json:"adf"`
	} `json:"to_adf"`
	ADFText struct {
		Doc  Object `json:"doc"`
		Text string `json:"text"`
	} `json:"adf_text"`
	GitHubMarkers []struct {
		Body string  `json:"body"`
		Op   *string `json:"op"`
	} `json:"github_markers"`
	JiraMarkerDoc struct {
		Doc Object `json:"doc"`
		Op  string `json:"op"`
		Has bool   `json:"has"`
	} `json:"jira_marker_doc"`
}

func loadGolden(t *testing.T) golden {
	data, err := os.ReadFile("testdata/golden.json")
	if err != nil {
		t.Fatal(err)
	}
	// Numbers decode as json.Number, exactly as API responses do.
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	var g golden
	if err := dec.Decode(&g); err != nil {
		t.Fatal(err)
	}
	return g
}

func TestPythonParityDigestsAndTokens(t *testing.T) {
	g := loadGolden(t)
	for i, d := range g.Digests {
		if got := digest(decodeJSON(mustMarshal(t, d.Value))); got != d.Digest {
			t.Errorf("digest %d (%q): got %s want %s", i, canonical(d.Value, false), got, d.Digest)
		}
	}
	c, err := ParseConfig(mustMarshal(t, g.Config))
	if err != nil {
		t.Fatal(err)
	}
	if binding(c) != g.Binding {
		t.Errorf("binding: got %s want %s", binding(c), g.Binding)
	}
	for _, tk := range g.Tokens {
		if got := token(c, OpKind(tk.Kind), fmt.Sprint(tk.ID)); got != tk.Token {
			t.Errorf("token %s/%v: got %s want %s", tk.Kind, tk.ID, got, tk.Token)
		}
	}
}

func TestPythonParityTextConversion(t *testing.T) {
	g := loadGolden(t)
	for _, a := range g.ToADF {
		if !sameJSON(toADF(a.Text), a.ADF) {
			t.Errorf("toADF(%q) = %s", a.Text, canonical(toADF(a.Text), false))
		}
	}
	text, err := adfText(decodeJSON(mustMarshal(t, g.ADFText.Doc)))
	if err != nil || text != g.ADFText.Text {
		t.Errorf("adfText = %q, %v; want %q", text, err, g.ADFText.Text)
	}
	for _, m := range g.GitHubMarkers {
		want := ""
		if m.Op != nil {
			want = *m.Op
		}
		if got := trailingMarker(Comment{Side: SideGitHub, Body: m.Body}); got != want {
			t.Errorf("trailingMarker(%q) = %q, want %q", m.Body, got, want)
		}
	}
	doc := Comment{Side: SideJira, Body: decodeJSON(mustMarshal(t, g.JiraMarkerDoc.Doc))}
	if trailingMarker(doc) != g.JiraMarkerDoc.Op || hasMarker(doc, g.JiraMarkerDoc.Op) != g.JiraMarkerDoc.Has {
		t.Error("Jira marker parity mismatch")
	}
}

func mustMarshal(t *testing.T, v any) []byte {
	t.Helper()
	data, err := json.Marshal(v)
	if err != nil {
		t.Fatal(err)
	}
	return data
}
